function buyer16(): int {global $a;$id=user14('commerce16');$a->wallet->adjust($id,'balance',500000,'f16:'.$id,'fixture');return $id;}
function lines16(int $id,int $qty=1): array{return [['kind'=>'content','item_id'=>$id,'variant_id'=>0,'quantity'=>$qty]];}
function address16(): array{return ['recipient'=>'Fixture Buyer','phone'=>'123456789','address'=>'Fixture Road 1','region'=>'CN-GD'];}
function buy16(int $uid,int $pid,int $qty=1,string $gateway='wallet',string $intent=''): array {global $a;$l=lines16($pid,$qty);$q=$a->checkout->quote(account($uid),$l,address16(),'');return $a->checkout->create($uid,$l,address16(),'',$gateway,$intent?:key32(),$q['total'],$q['currency']);}
function unit16(array $sale): array {global $a;return $a->db->one('SELECT * FROM cy_orders WHERE sale_id=? ORDER BY id',[(int)$sale['id']]);}
settings('checkout',['checkout_enabled'=>1,'guest_checkout_enabled'=>1,'shipping_enabled'=>1,'promotions_enabled'=>1,'upgrades_enabled'=>1]);
settings('direct_payments',['stripe_enabled'=>1,'stripe_secret'=>'sk_test_fixture','stripe_webhook_secret'=>'whsec_fixture']);
$a->db->execute('UPDATE cy_promotions SET active=0');
